insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('indoor-plants', 'Type', 'Indoor Plants', 'Indoor', 'Shop nursery-grown indoor plants online in India — from Monstera to ZZ plants. Hand-raised, delivered fresh, with a 30-day happiness guarantee.', 'Our indoor plants are raised under shade-house conditions that mimic Indian homes, so they settle in quickly once they reach yours. Every plant is acclimatised for a minimum of six weeks before it ships.', 'https://images.unsplash.com/photo-1556228453-efd6c1ff04f6?auto=format&fit=crop', '{"match":"all","space":["desk","floor","hanging"]}'::jsonb, 'published', 0) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('outdoor-plants', 'Type', 'Outdoor & Garden Plants', 'Outdoor', 'Sun-hardy outdoor plants for balconies, terraces and gardens. Grown in open soil at our nursery and delivered across India.', 'Raised in open soil under real sky, our outdoor plants are already used to Indian summers and monsoons. Ideal for balconies, terraces, entrances and garden beds.', 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop', '{"match":"any","space":["outdoor"],"light":["sun"]}'::jsonb, 'published', 1) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('pet-friendly-plants', 'Need', 'Pet-Friendly Plants', 'Pet friendly', 'Non-toxic, pet-safe plants for homes with cats and dogs. Calathea, orchids, spider plants and more — delivered across India.', 'Every plant here is listed as non-toxic to cats and dogs, so curious noses and nibbling teeth are no cause for worry.', 'https://images.unsplash.com/photo-1491147334573-44cbb4602074?auto=format&fit=crop', '{"match":"all","petSafe":true}'::jsonb, 'published', 2) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('low-light-plants', 'Light', 'Low Light Plants', 'Low light', 'Plants that thrive in low light — perfect for north-facing rooms, corridors and offices. Shop ZZ, snake plants and pothos online.', 'No bright window? No problem. These are the plants we trust in dim corridors, north-facing flats and offices with more tube-light than sunlight.', 'https://images.unsplash.com/photo-1632207691143-643e2a9a9361?auto=format&fit=crop', '{"match":"all","light":["low"]}'::jsonb, 'published', 3) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('bright-light-plants', 'Light', 'Bright Light Plants', 'Bright light', 'Indoor plants for bright rooms and big windows — fiddle leaf figs, Monstera, orchids and more, grown at our nursery.', 'For rooms flooded with daylight. These plants reward a bright spot near a big window with bold, fast growth.', 'https://images.unsplash.com/photo-1453904300235-0f2f60b15b5d?auto=format&fit=crop', '{"match":"all","light":["bright"]}'::jsonb, 'published', 4) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('full-sun-plants', 'Light', 'Full Sun Plants', 'Full sun', 'Sun-loving plants for terraces, balconies and south-facing windows. Cactus, succulents, eucalyptus and topiary.', 'Built for the Indian sun. These plants want four to six hours of direct sunlight and will happily bake on a terrace.', 'https://images.unsplash.com/photo-1463936575829-25148e1db1b8?auto=format&fit=crop', '{"match":"all","light":["sun"]}'::jsonb, 'published', 5) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('easy-care-plants', 'Need', 'Easy Care Plants for Beginners', 'Easy care', 'Hard-to-kill, low-maintenance plants for beginners and busy people. Forgiving, beautiful and delivered with a care card.', 'New to plants, or simply busy? These are forgiving, low-maintenance companions that tolerate the odd missed watering.', 'https://images.unsplash.com/photo-1611211232932-da3113c5b960?auto=format&fit=crop', '{"match":"all","careMax":1}'::jsonb, 'published', 6) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('air-purifying-plants', 'Need', 'Air-Purifying Plants', 'Air purifying', 'Air-purifying indoor plants like snake plant, pothos, spider plant and rubber plant — fresher-feeling rooms, naturally.', 'Leafy, hardworking plants long associated with cleaner-feeling indoor air — and a calmer room. Great for bedrooms and workspaces.', 'https://images.unsplash.com/photo-1604762524889-3e2fcc145683?auto=format&fit=crop', '{"match":"all","includeIds":["snake","pothos","spider","rubber","zz","calathea"]}'::jsonb, 'published', 7) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('plant-gifts', 'Need', 'Plant Gifts', 'Gifts', 'Thoughtful plant gifts delivered across India — gift-wrapped in linen with a hand-written note. Perfect for birthdays and housewarmings.', 'A plant is a gift that grows. Each order can be wrapped in linen with prices hidden and a note written by hand at the nursery.', 'https://images.unsplash.com/photo-1610397648930-477b8c7f0943?auto=format&fit=crop', '{"match":"all","priceMax":1700,"sizes":["S","M"]}'::jsonb, 'published', 8) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('living-room-plants', 'Room', 'Living Room Plants', 'Living room', 'Statement floor plants and leafy companions for your living room — Monstera, fiddle leaf fig, rubber plant and more.', 'Statement plants that anchor a room — sculptural floor specimens and lush companions for shelves and side tables.', 'https://images.unsplash.com/photo-1556228453-efd6c1ff04f6?auto=format&fit=crop', '{"match":"all","space":["floor"],"excludeSpace":["outdoor"]}'::jsonb, 'published', 9) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('bedroom-plants', 'Room', 'Bedroom Plants', 'Bedroom', 'Calm, air-purifying bedroom plants that cope with softer light — snake plants, ZZ, calathea and more.', 'Quiet, soft-light-loving plants for the room where you rest. Many release oxygen through the night.', 'https://images.unsplash.com/photo-1604762524889-3e2fcc145683?auto=format&fit=crop', '{"match":"all","light":["low","medium"],"excludeSpace":["outdoor"]}'::jsonb, 'published', 10) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('balcony-plants', 'Room', 'Balcony & Terrace Plants', 'Balcony', 'Hardy balcony and terrace plants for Indian weather — sun-lovers, topiary and fragrant eucalyptus, grown in open soil.', 'Hardy plants raised in open soil that shrug off heat, wind and the monsoon. Perfect for balconies of every size.', 'https://images.unsplash.com/photo-1585320806297-9794b3e4eeae?auto=format&fit=crop', '{"match":"any","space":["outdoor"],"light":["sun"]}'::jsonb, 'published', 11) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('office-desk-plants', 'Room', 'Office & Desk Plants', 'Workspace', 'Compact, low-fuss desk plants for offices and work-from-home setups. Tolerant of AC and artificial light.', 'Compact, low-fuss plants that cope with AC and artificial light — perfect for desks, reception counters and home offices.', 'https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop', '{"match":"all","space":["desk"],"light":["low","medium"]}'::jsonb, 'published', 12) on conflict (slug) do nothing;
insert into public.collections (slug, grp, title, short, description, intro, image_url, rules, status, sort_order) values ('kitchen-plants', 'Room', 'Kitchen Plants', 'Kitchen', 'Humidity-loving and compact plants for kitchen windowsills and counters.', 'Small, humidity-loving plants that thrive on a bright kitchen sill and bring life to the busiest room in the house.', 'https://images.unsplash.com/photo-1586208958839-06c17cacdf08?auto=format&fit=crop', '{"match":"all","space":["desk","hanging"],"light":["medium","bright"]}'::jsonb, 'published', 13) on conflict (slug) do nothing;
